{
  "description": "The creature is a quadrupedal hybrid shown in side profile facing right, with a pale, smooth-skinned axolotl-like head, body and limbs combined with a dense covering of overlapping pangolin-like scales over its back and tail. It has a blunt snout, large dark eyes, and six feathery pink external gills around the neck, a thick arched torso with wrinkled pale underbelly skin, four stout splayed legs ending in clawed feet, and a long thick tail that extends to the left and is also covered in scales.",
  "parts": [
    {
      "part": "head",
      "looks_like": "pale grayish-white, smooth and slightly mottled with small dark speckles, blunt rounded snout with small nostrils, large round dark eyes with light blue-gray irises, and a closed mouth giving a slight smile",
      "where": "at the front right end of the body"
    },
    {
      "part": "gills",
      "looks_like": "six feathery pink external gill stalks with fine branching filaments, three on each side of the neck behind the head, pale pink shafts with reddish fringe",
      "where": "projecting outward from both sides of the neck just behind the head"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping keratinous scales in dark brown to gray with lighter tan edges, arranged in neat diagonal rows like armor, with a glossy textured surface",
      "where": "covering the entire dorsal surface from the neck over the back and continuing down the full length of the tail"
    },
    {
      "part": "legs",
      "looks_like": "four thick, fleshy, pale gray limbs with wrinkled skin and visible folds at the joints, splayed outward in a low stance",
      "where": "underneath the body, two forelegs under the chest and two hindlegs under the rear"
    },
    {
      "part": "feet",
      "looks_like": "broad clawed feet with four to five short digits each tipped with small dark claws, with textured skin on top and pads underneath",
      "where": "at the ends of each leg planted on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick and tapering, fully covered on top and sides with the same overlapping dark scales, with a paler smooth underside visible at the base",
      "where": "extending to the left from the rear of the body"
    },
    {
      "part": "markings",
      "looks_like": "pale mottled skin with subtle gray speckling on the head and faint transverse wrinkled ridges on the pale belly and limb joints",
      "where": "on the exposed skin of the head, throat, belly, and legs not covered by scales"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
